//hue is angle mouse to (nearest point to current pixel)

#define PI 3.14159265358979323846
#define PI2 6.28318530717958647693

#define pointsLen 10
vec2 points[pointsLen] = vec2[](
    vec2(0.1, 0.1),
    vec2(0.3, 0.2),
    vec2(0.5, 0.1),
    vec2(0.7, 0.3),
    vec2(0.9, 0.2),
    vec2(0.1, 0.5),
    vec2(0.3, 0.7),
    vec2(0.5, 0.9),
    vec2(0.7, 0.5),
    vec2(0.9, 0.8)
);

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord / iResolution.xy;
    vec2 mouse = iMouse.xy / iResolution.xy;

    // Avoid dull initial
    if (iMouse.x <= 0.0) {
        mouse = vec2(0.7, 0.4); // Default mouse position
    }

    // Find the nearest point to the current pixel
    float minDistance = 1e6; // Start with a large number
    vec2 nearestPoint = vec2(0.0);

    for (int i = 0; i < pointsLen; i++) {
        float distance = length(uv - points[i]);
        if (distance < minDistance) {
            minDistance = distance;
            nearestPoint = points[i];
        }
    }

    // angle from the mouse to the nearest point
    vec2 v = nearestPoint - mouse;
    float angle = atan(v.y, v.x); // in radians

    float hue = (angle + PI) / PI2; // Map angle to [0, 1]

    // Use the distance to the nearest point for brightness
    float brightness =clamp(1.0 - minDistance*2., 0.0, 1.0); // Invert distance for brightness


    vec3 col = vec3(hue, 0.0, 0.0);

    // Convert HSV to RGB
    float r = abs(col.x * 6.0 - 3.0) - 1.0;
    float g = 2.0 - abs(col.x * 6.0 - 2.0);
    float b = 2.0 - abs(col.x * 6.0 - 4.0);
    col = clamp(vec3(r, g, b), 0.0, 1.0) * brightness; // Apply brightness

    fragColor = vec4(col, 1.0);
}
